-- +goose StatementBegin
CREATE FUNCTION photo.billing_guard_operation_item() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF (NEW.id,NEW.tenant_id,NEW.request_id,NEW.task_id,NEW.source_version_id,NEW.original_digest,NEW.policy_hash,NEW.policy_id,NEW.resource_code,NEW.quantity)
 IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.request_id,OLD.task_id,OLD.source_version_id,OLD.original_digest,OLD.policy_hash,OLD.policy_id,OLD.resource_code,OLD.quantity)
 OR (OLD.claim_id IS NOT NULL AND NEW.claim_id IS DISTINCT FROM OLD.claim_id)
 OR (OLD.state<>'accepted' AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'BILLING_OPERATION_ITEM_IMMUTABLE' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER billing_operation_item_immutable BEFORE UPDATE ON photo.billing_operation_items FOR EACH ROW EXECUTE FUNCTION photo.billing_guard_operation_item();
CREATE TRIGGER billing_operation_request_immutable BEFORE UPDATE ON photo.billing_operation_requests FOR EACH ROW EXECUTE FUNCTION photo.reject_content_update('id','tenant_id','run_id','period_id','request_hash','created_at');
ALTER FUNCTION photo.billing_guard_operation_item() OWNER TO photo_fn_owner;
REVOKE ALL ON FUNCTION photo.billing_guard_operation_item() FROM PUBLIC,photo_api,photo_scheduler,photo_worker;

